enum Direction = { North, South, East, West };
enum Location = { EasternCrosswalk };

array[1..1] of var Location: pedestrianLocation;
array[1..4] of var Direction: vehicleDirection;

% Constraints
constraint pedestrianLocation[1] = EasternCrosswalk;

constraint forall(i in 1..4)(
    vehicleDirection[i] in Direction
);

% The pedestrian using the eastern crosswalk always goes before any car approaching from the East
constraint (pedestrianLocation[1] = EasternCrosswalk) -> 
           (exists(i in 1..4)(vehicleDirection[i] = East)) /\ 
           (forall(j in 1..4)(vehicleDirection[j] != East -> vehicleDirection[j] < pedestrianLocation[1]));

% Vehicles (and the pedestrian) go in the order they arrive at the intersection unless otherwise specified by right-of-way rules
% (This will be ensured by the following constraints)

% The pedestrian and the East car arrive at the same moment
constraint (exists(i in 1..4)(vehicleDirection[i] = East)) -> 
           (pedestrianLocation[1] = EasternCrosswalk);

% The South car arrives before both the pedestrian and the East car
constraint (exists(i in 1..4)(vehicleDirection[i] = South)) -> 
           (pedestrianLocation[1] < vehicleDirection[i]) /\ 
           (exists(j in 1..4)(vehicleDirection[j] = East) -> pedestrianLocation[1] < vehicleDirection[j]);

% The North car and the West car arrive at the same moment, after both the pedestrian and the East car
constraint (exists(i in 1..4)(vehicleDirection[i] = North)) /\ 
           (exists(j in 1..4)(vehicleDirection[j] = West)) -> 
           (pedestrianLocation[1] < vehicleDirection[i]) /\ 
           (exists(k in 1..4)(vehicleDirection[k] = East) -> pedestrianLocation[1] < vehicleDirection[k]);

% The South car must go first based on its earlier arrival
constraint (exists(i in 1..4)(vehicleDirection[i] = South));

% The pedestrian must go before the East car due to the pedestrian’s priority
constraint (pedestrianLocation[1] < (exists(i in 1..4)(vehicleDirection[i] = East)));

% Among the North car and West car, the North car must go first, followed by the West car, since they arrive simultaneously after the pedestrian and East car
constraint (exists(i in 1..4)(vehicleDirection[i] = North)) /\ 
           (exists(j in 1..4)(vehicleDirection[j] = West)) -> 
           (vehicleDirection[i] < vehicleDirection[j]);

